import {NextResponse}from'next/server';import pool from'@/lib/db';import{requireRole,unauthorized}from'@/lib/auth';import{ensureProjectManagementSchema,pageParams}from'@/lib/project-management';
export async function GET(req){if(!requireRole(req,'admin'))return unauthorized();try{await ensureProjectManagementSchema();const s=new URL(req.url).searchParams,{page,pageSize,offset}=pageParams(s),q=String(s.get('search')||'').trim();const r=await pool.query(`SELECT *,COUNT(*) OVER()::int total_count FROM pm_vendors WHERE $1='' OR name ILIKE '%'||$1||'%' OR COALESCE(phone,'') ILIKE '%'||$1||'%' ORDER BY name LIMIT $2 OFFSET $3`,[q,pageSize,offset]);const total=Number(r.rows[0]?.total_count||0);return NextResponse.json({success:true,data:r.rows,pagination:{page,pageSize,total,totalPages:Math.ceil(total/pageSize)}})}catch(e){return NextResponse.json({success:false,error:e.message},{status:500})}}
export async function POST(req){if(!requireRole(req,'admin'))return unauthorized();try{await ensureProjectManagementSchema();const b=await req.json(),name=String(b.name||'').trim();if(!name)return NextResponse.json({success:false,error:'Vendor name is required'},{status:400});const r=await pool.query(`INSERT INTO pm_vendors(name,phone,trade,address,is_active)VALUES($1,$2,$3,$4,$5)RETURNING *`,[name,b.phone||null,b.trade||null,b.address||null,b.is_active!==false]);return NextResponse.json({success:true,data:r.rows[0]},{status:201})}catch(e){return NextResponse.json({success:false,error:e.message},{status:500})}}
